        let mut parsed = parse_markdown_file(&root, &file, &text)?;
        cards.append(&mut parsed);
    }

    let tex_macros = parse_macros(&root)?;

    Ok(ParsedCollection {
        root,
        cards,
        tex_macros,
    })
}

pub fn validate_media(collection: &ParsedCollection) -> Result<(), String> {
    let mut missing = BTreeSet::new();

    for card in &collection.cards {
        let markdown = match &card.content {
            CardContent::Basic { question, answer } => {
                vec![question.as_str(), answer.as_str()]
            }
            CardContent::Cloze { raw_source, .. } => vec![raw_source.as_str()],
        };

