            for media_ref in extract_media_refs(fragment) {
                let target = resolve_media_path(
                    &collection.root,
                    &card.file_path,
                    &media_ref.path,
                );
                if !target.exists() {
                    missing.insert((
                        media_ref.path,
                        card.file_path.display().to_string(),
                        card.line_start,
                    ));
                }
            }
        }
    }

    if missing.is_empty() {
        return Ok(());
    }

    let mut message = String::from("Missing media files referenced in cards:\n");
    for (media_path, file_path, line_start) in missing {
        message.push_str(&format!(
            "  - {} (referenced in {}:{})\n",
            media_path, file_path, line_start
        ));
    }
    Err(message)
}

fn parse_markdown_file(root: &Path, file_path: &Path, text: &str) -> Result<Vec<Card>, String> {
    let lines: Vec<&str> = text.lines().collect();
    let mut cards = Vec::new();
    let mut index = 0usize;

