                };
                spans.push((start, end));
                continue;
            }
            plain.push('[');
            plain.push_str(&inner);
            break;
        }
        plain.push(ch);
    }

    plain.push_str(chars.collect::<String>().as_str());
    (plain, spans)
}

#[derive(Debug)]
struct MediaRef {
    path: String,
}

fn extract_media_refs(markdown: &str) -> Vec<MediaRef> {
    let bytes = markdown.as_bytes();
    let mut refs = Vec::new();
    let mut i = 0usize;

    while i + 3 < bytes.len() {
        if bytes[i] == b'!' && bytes[i + 1] == b'[' {
            let mut j = i + 2;
            while j < bytes.len() && bytes[j] != b']' {
                j += 1;
            }
            if j + 1 < bytes.len() && bytes[j + 1] == b'(' {
                let mut k = j + 2;
                while k < bytes.len() && bytes[k] != b')' {
                    k += 1;
                }
                if k < bytes.len() {
                    let path = &markdown[j + 2..k];
                    refs.push(MediaRef {
                        path: path.to_string(),
                    });
                    i = k + 1;
                    continue;
                }
            }
        }
        i += 1;
    }

    refs
}

fn resolve_media_path(root: &Path, file_path: &Path, media_path: &str) -> PathBuf {
    if let Some(rest) = media_path.strip_prefix("@/") {
        root.join(rest)
    } else {
        file_path
            .parent()
            .unwrap_or(root)
            .join(media_path)
    }
}

fn basic_hash(question: &str, answer: &str) -> String {
    let mut data = Vec::new();
    data.extend_from_slice(question.as_bytes());
    data.push(0);
    data.extend_from_slice(answer.as_bytes());
    blake3::hash(&data).to_hex().to_string()
}

fn cloze_family_hash(text: &str) -> String {
    blake3::hash(text.as_bytes()).to_hex().to_string()
}

fn cloze_hash(text: &str, start: usize, end: usize) -> String {
    let mut data = Vec::new();
    data.extend_from_slice(text.as_bytes());
    data.push(0);
    data.extend_from_slice(start.to_string().as_bytes());
    data.push(0);
    data.extend_from_slice(end.to_string().as_bytes());
    blake3::hash(&data).to_hex().to_string()
}

