pub fn render_card_page(
    card: &Card,
    revealed: bool,
    progress_percent: usize,
    answer_controls: AnswerControls,
    undo_enabled: bool,
    collection_root: &Path,
) -> String {
    let body = match &card.content {
        CardContent::Basic { question, answer } => {
            let question_html = render_markdown(question, &card.file_path, collection_root);
            let answer_html = if revealed {
                render_markdown(answer, &card.file_path, collection_root)
            } else {
                String::new()
            };
            format!(
                "<div class=\"question rich-text\">{}</div><div class=\"answer rich-text\">{}</div>",
                question_html, answer_html
            )
        }
        CardContent::Cloze { text, start, end, .. } => {
            let prompt_html = render_cloze_prompt(
                text,
                *start,
                *end,
                revealed,
                &card.file_path,
                collection_root,
            );
            format!("<div class=\"prompt rich-text\">{}</div>", prompt_html)
        }
    };

    let controls = render_controls(revealed, answer_controls, undo_enabled);
    format!(
        "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>hashcards</title><link rel=\"stylesheet\" href=\"/katex/katex.css\"><link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/styles/github.min.css\"><script defer src=\"/katex/katex.js\"></script><script defer src=\"/katex/mhchem.js\"></script><script defer src=\"https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/highlight.min.js\"></script><link rel=\"stylesheet\" href=\"/style.css\"><style>.card-content {{ opacity: 0; }}</style><noscript><style>.card-content {{ opacity: 1; }}</style></noscript></head><body><div class=\"root\"><div class=\"header\"><div class=\"progress-bar\"><div class=\"progress-fill\" style=\"width: {}%;\"></div></div></div><div class=\"card-container\"><div class=\"card\"><div class=\"card-header\"><h1>{}</h1></div><div class=\"card-content\">{}</div></div></div><div class=\"controls\"><form action=\"/\" method=\"post\">{}</form></div></div><script src=\"/script.js\"></script></body></html>",
        progress_percent,
        html_escape(&card.deck_name),
        body,
        controls
    )
}

pub fn render_finished_page(
