fn render_controls(revealed: bool, answer_controls: AnswerControls, undo_enabled: bool) -> String {
    let undo = if undo_enabled {
        "<input id=\"undo\" type=\"submit\" name=\"action\" value=\"Undo\" title=\"Undo last action. Shortcut: u.\">"
    } else {
        "<input id=\"undo\" type=\"submit\" name=\"action\" value=\"Undo\" disabled>"
    };

    let middle = if !revealed {
        "<input id=\"reveal\" type=\"submit\" name=\"action\" value=\"Reveal\" title=\"Show the answer. Shortcut: space.\">".to_string()
    } else {
        match answer_controls {
            AnswerControls::Full => "<div class=\"grades\"><input id=\"forgot\" type=\"submit\" name=\"action\" value=\"Forgot\" title=\"Mark card as forgotten. Shortcut: 1.\"><input id=\"hard\" type=\"submit\" name=\"action\" value=\"Hard\" title=\"Mark card as difficult. Shortcut: 2.\"><input id=\"good\" type=\"submit\" name=\"action\" value=\"Good\" title=\"Mark card as remembered well. Shortcut: 3.\"><input id=\"easy\" type=\"submit\" name=\"action\" value=\"Easy\" title=\"Mark card as very easy. Shortcut: 4.\"></div>".to_string(),
            AnswerControls::Binary => "<div class=\"grades\"><input id=\"forgot\" type=\"submit\" name=\"action\" value=\"Forgot\" title=\"Mark card as forgotten.\"><input id=\"good\" type=\"submit\" name=\"action\" value=\"Good\" title=\"Mark card as remembered.\"></div>".to_string(),
        }
    };

    format!(
        "{}<div class=\"spacer\"></div>{}<div class=\"spacer\"></div><input id=\"end\" type=\"submit\" name=\"action\" value=\"End\" title=\"End the session (changes are saved)\">",
        undo, middle
    )
}

fn render_cloze_prompt(
    text: &str,
    start: usize,
    end: usize,
    revealed: bool,
    file_path: &Path,
    root: &Path,
) -> String {
    let chars: Vec<char> = text.chars().collect();
    let left: String = chars[..start.min(chars.len())].iter().collect();
    let right_start = (end + 1).min(chars.len());
    let middle: String = if start <= end && start < chars.len() {
        chars[start..=end.min(chars.len().saturating_sub(1))]
            .iter()
            .collect()
    } else {
        String::new()
    };
    let right: String = chars[right_start..].iter().collect();

    let placeholder = if revealed {
        format!(
            "<span class='cloze-reveal'>{}</span>",
            html_escape(&middle)
        )
    } else {
        "<span class='cloze'>.............</span>".to_string()
    };

    let markdown = format!("{}{}{}", left, placeholder, right);
    render_markdown(&markdown, file_path, root)
}

fn render_markdown(markdown: &str, file_path: &Path, root: &Path) -> String {
    let rewritten_media = rewrite_media(markdown, file_path, root);
    let rewritten_math = rewrite_math(&rewritten_media);
    let mut html_out = String::new();
    let parser = Parser::new_ext(&rewritten_math, Options::all());
    html::push_html(&mut html_out, parser);
    html_out
}

fn rewrite_media(markdown: &str, file_path: &Path, root: &Path) -> String {
    let bytes = markdown.as_bytes();
    let mut out = String::new();
    let mut i = 0usize;

    while i + 3 < bytes.len() {
        if bytes[i] == b'!' && bytes[i + 1] == b'[' {
            let mut j = i + 2;
            while j < bytes.len() && bytes[j] != b']' {
                j += 1;
            }
            if j + 1 < bytes.len() && bytes[j + 1] == b'(' {
                let mut k = j + 2;
                while k < bytes.len() && bytes[k] != b')' {
                    k += 1;
                }
                if k < bytes.len() {
                    let alt = &markdown[i + 2..j];
                    let path = &markdown[j + 2..k];
                    let url = media_url(path, file_path, root);
                    if is_audio(path) {
                        out.push_str(&format!(
                            "<audio controls src=\"{}\"></audio>",
                            url
                        ));
                    } else {
                        out.push_str(&format!("![{}]({})", alt, url));
                    }
                    i = k + 1;
                    continue;
                }
            }
        }
        out.push(bytes[i] as char);
        i += 1;
    }
    out.push_str(&markdown[i..]);
    out
}

fn rewrite_math(markdown: &str) -> String {
    let mut out = String::new();
    let bytes = markdown.as_bytes();
    let mut i = 0usize;

    while i < bytes.len() {
        if i + 1 < bytes.len() && bytes[i] == b'$' && bytes[i + 1] == b'$' {
            if let Some(end) = markdown[i + 2..].find("$$") {
                let inner = &markdown[i + 2..i + 2 + end];
                out.push_str("<span class=\"math math-display\">");
                out.push_str(&html_escape(inner));
                out.push_str("</span>");
                i += 2 + end + 2;
                continue;
            }
        }
        if bytes[i] == b'$' {
            if let Some(end) = markdown[i + 1..].find('$') {
                let inner = &markdown[i + 1..i + 1 + end];
                out.push_str("<span class=\"math math-inline\">");
                out.push_str(&html_escape(inner));
                out.push_str("</span>");
                i += 1 + end + 1;
                continue;
            }
        }
        out.push(bytes[i] as char);
        i += 1;
    }

    out
}

fn media_url(path: &str, file_path: &Path, root: &Path) -> String {
    if let Some(rest) = path.strip_prefix("@/") {
        format!("/asset/root?path={}", url_encode(rest))
    } else {
        let base = relative_parent(file_path, root);
        format!(
            "/asset/relative?base={}&path={}",
