pub async fn run(collection: ParsedCollection, db_path: PathBuf, options: DrillOptions) -> Result<(), String> {
    let started_at = Utc::now();
    let started_at_iso = started_at.format("%Y-%m-%dT%H:%M:%S%.3f").to_string();
    let started_display = started_at
        .with_timezone(&Local)
        .format("%Y-%m-%d %H:%M:%S")
        .to_string();
    let today = started_at.format("%Y-%m-%d").to_string();

    let conn = db::open_or_init(&db_path)?;
    let existing_rows = db::load_card_rows(&conn)?;

    let mut cards = collection.cards;
    if let Some(deck) = &options.from_deck {
        cards.retain(|card| &card.deck_name == deck);
    }

    let mut due_cards: Vec<Card> = cards
        .iter()
        .filter(|card| {
            existing_rows
                .get(&card.hash)
                .map(|row| {
                    row.review_count > 0
                        && row
                            .due_date
                            .as_deref()
                            .map(|date| date <= today.as_str())
                            .unwrap_or(false)
                })
                .unwrap_or(false)
        })
        .cloned()
        .collect();
    let mut new_cards: Vec<Card> = cards
        .into_iter()
        .filter(|card| {
            existing_rows
                .get(&card.hash)
                .map(|row| row.review_count == 0)
                .unwrap_or(true)
        })
        .collect();

    due_cards.sort_by(|a, b| b.sort_hash_desc.cmp(&a.sort_hash_desc));
    new_cards.sort_by(|a, b| b.sort_hash_desc.cmp(&a.sort_hash_desc));

    if options.bury_siblings {
        due_cards = bury_siblings(due_cards);
        new_cards = bury_siblings(new_cards);
    }

    let default_new_limit = 1usize;
    if let Some(limit) = options.new_card_limit.or(Some(default_new_limit)) {
        new_cards.truncate(limit);
    }

    let mut selected = due_cards;
    selected.extend(new_cards);
    if options.bury_siblings {
        selected = bury_siblings(selected);
    }
    if let Some(limit) = options.card_limit {
        selected.truncate(limit);
    }

    if selected.is_empty() {
        println!("No cards due today.");
        return Ok(());
    }

    let all_hashes: Vec<String> = collection.cards.iter().map(|card| card.hash.clone()).collect();
    db::sync_cards_for_drill(&conn, &all_hashes, &started_at_iso)?;
    let session_id = db::next_session_id(&conn)?;
    db::insert_session(&conn, session_id, &started_at_iso, &started_at_iso)?;

    let macros = collection
        .tex_macros
        .into_iter()
        .map(|item| (item.name, item.replacement))
        .collect::<Vec<_>>();

    let runtime = RuntimeState {
        cards: selected,
        current_index: 0,
        revealed: false,
        reviewed: Vec::new(),
        started_at,
        session_id,
        answer_controls: options.answer_controls,
        finished: None,
    };

    let state = AppState {
        runtime: Arc::new(Mutex::new(runtime)),
        db_path,
        collection_root: collection.root,
        macros,
        shutdown: Arc::new(Notify::new()),
    };

    let app = Router::new()
        .route("/", get(get_root).post(post_root))
        .route("/style.css", get(get_style))
        .route("/script.js", get(get_script))
        .route("/katex/katex.css", get(get_katex_css))
        .route("/katex/katex.js", get(get_katex_js))
        .route("/katex/mhchem.js", get(get_mhchem_js))
        .route("/asset/root", get(get_root_asset))
        .route("/asset/relative", get(get_relative_asset))
        .with_state(state.clone());

    let listener = TcpListener::bind(format!("{}:{}", options.host, options.port))
        .await
        .map_err(|err| err.to_string())?;

    if options.open_browser {
        let url = format!("http://{}:{}", options.host, options.port);
        open_browser_best_effort(&url);
    }

    axum::serve(listener, app)
        .with_graceful_shutdown(state.shutdown.notified())
        .await
        .map_err(|err| err.to_string())
}

