        due_date: next_row.due_date.clone().unwrap_or_default(),
    };

    db::insert_review(&conn, &review)?;
    db::update_card_row(&conn, &card.hash, &next_row)?;

    runtime.reviewed.push(ReviewAction {
        card_index: runtime.current_index,
        previous_row,
        review_id,
    });
    runtime.current_index += 1;
    runtime.revealed = false;

    if runtime.current_index >= runtime.cards.len() {
        finish_session(runtime, state)?;
    }

    Ok(())
}

fn finish_session(runtime: &mut RuntimeState, state: &AppState) -> Result<(), String> {
    let finished_at = Utc::now();
    let finished_at_iso = finished_at.format("%Y-%m-%dT%H:%M:%S%.3f").to_string();
    let finished_at_local = finished_at
        .with_timezone(&Local)
        .format("%Y-%m-%d %H:%M:%S")
        .to_string();
    let duration = finished_at.signed_duration_since(runtime.started_at);
    let duration_seconds = duration.num_seconds().max(0);
    let reviewed = runtime.reviewed.len();
    let pace = if reviewed == 0 {
        0.0
    } else {
        duration_seconds as f64 / reviewed as f64
    };

    let conn = db::open_or_init(&state.db_path)?;
    db::update_session_end(&conn, runtime.session_id, &finished_at_iso)?;

    runtime.finished = Some(FinishedState {
        total_cards: runtime.cards.len(),
        cards_reviewed: reviewed,
        started_at_local: runtime
            .started_at
            .with_timezone(&Local)
            .format("%Y-%m-%d %H:%M:%S")
            .to_string(),
        finished_at_local,
        duration_seconds,
        pace_seconds: pace,
    });

    Ok(())
}

fn scheduled_row(previous: &CardRow, grade: Grade, now: &DateTime<Utc>) -> CardRow {
    let (stability, difficulty, interval_raw) = if previous.review_count == 0 {
        match grade {
            Grade::Forgot => (0.4, 7.0, 1.0),
            Grade::Hard => (1.2, 6.0, 1.0),
            Grade::Good => (3.173, 5.282434422319005, 3.172999999999999),
            Grade::Easy => (7.0, 4.0, 8.0),
        }
    } else {
        let prev_stability = previous.stability.unwrap_or(1.0);
        let prev_difficulty = previous.difficulty.unwrap_or(5.0);
        let prev_interval = previous.interval_raw.unwrap_or(1.0);
        match grade {
            Grade::Forgot => (0.8, (prev_difficulty + 1.2).min(10.0), 1.0),
            Grade::Hard => (
                (prev_stability * 1.15).max(1.0),
                (prev_difficulty + 0.15).min(10.0),
                (prev_interval * 1.2).max(1.0),
            ),
            Grade::Good => (
                (prev_stability * 1.8).max(prev_stability + 0.5),
                (prev_difficulty - 0.1).max(1.0),
                (prev_interval * 2.2).max(1.0),
            ),
            Grade::Easy => (
                (prev_stability * 2.4).max(prev_stability + 1.0),
                (prev_difficulty - 0.3).max(1.0),
                (prev_interval * 3.4).max(2.0),
            ),
        }
    };

    let interval_days = interval_raw.round().max(1.0) as i64;
    let due_date = (now.date_naive() + Duration::days(interval_days)).to_string();

    CardRow {
        added_at: previous.added_at.clone(),
        last_reviewed_at: Some(now.format("%Y-%m-%dT%H:%M:%S%.3f").to_string()),
        stability: Some(stability),
        difficulty: Some(difficulty),
        interval_raw: Some(interval_raw),
        interval_days: Some(interval_days),
        due_date: Some(due_date),
        review_count: previous.review_count + 1,
    }
}

fn open_browser_best_effort(url: &str) {
    #[cfg(target_os = "linux")]
    {
        let _ = std::process::Command::new("xdg-open").arg(url).spawn();
    }
    #[cfg(target_os = "macos")]
    {
        let _ = std::process::Command::new("open").arg(url).spawn();
    }
    #[cfg(target_os = "windows")]
    {
        let _ = std::process::Command::new("cmd")
            .args(["/C", "start", url])
            .spawn();
    }
}

