                CardContent::Basic { question, answer } => ExportContent::Basic {
                    question: question.clone(),
                    answer: answer.clone(),
                },
                CardContent::Cloze { text, start, end, .. } => ExportContent::Cloze {
                    text: text.clone(),
                    start: *start,
                    end: *end,
                },
            };

            ExportCard {
                hash: card.hash.clone(),
                family_hash: card.family_hash.clone(),
                deck_name: card.deck_name.clone(),
                location: ExportLocation {
                    file_path: card.file_path.display().to_string(),
                    line_start: card.line_start,
                    line_end: card.line_end,
                },
                content,
                performance,
            }
        })
        .collect::<Vec<_>>();

    export_cards.sort_by(|a, b| a.hash.cmp(&b.hash));

    let export_sessions = sessions
        .into_iter()
        .map(|session| ExportSession {
            session_id: session.session_id,
            started_at: session.started_at,
            ended_at: session.ended_at,
            reviews: reviews_by_session.remove(&session.session_id).unwrap_or_default(),
        })
        .collect::<Vec<_>>();

    Ok(ExportCollection {
        cards: export_cards,
        sessions: export_sessions,
    })
}

fn print_json<T: serde::Serialize>(value: &T) -> Result<(), String> {
    let json = serde_json::to_string_pretty(value).map_err(|err| err.to_string())?;
    println!("{json}");
    Ok(())
}

fn collection_dir(directory: Option<PathBuf>) -> PathBuf {
    directory.unwrap_or_else(|| std::env::current_dir().unwrap_or_else(|_| PathBuf::from(".")))
}

